use betterlite_models::decisions::Json;

use crate::web_replay::flatten_web_search_results;

fn messages(source: &str) -> Vec<Json> {
    serde_json::from_str(source).unwrap()
}

fn flatten(source: &str) -> Vec<Json> {
    flatten_web_search_results(&messages(source))
}

#[test]
fn case_1_unencrypted_search_result() {
    let source = r#"[{"role":"assistant","content":[{"type":"server_tool_use","id":"s1","name":"web_search","input":{"query":"rust async"}},{"type":"web_search_tool_result","tool_use_id":"s1","content":[{"type":"web_search_result","url":"https://a.example","title":"A","snippet":"first","extra":{"keep":true}},{"type":"web_search_result","url":"https://b.example"}]}]},{"role":"user","content":[{"type":"web_search_tool_result","tool_use_id":"s2","content":[{"type":"web_search_result"},{"type":"web_search_result","title":"T","snippet":"S"}]}]},{"role":"assistant","content":[{"type":"web_search_tool_result","tool_use_id":"s3","content":{"type":"web_search_tool_result_error","error_code":"too_many_requests"}},{"type":"web_search_tool_result","tool_use_id":"s4","content":{"type":"web_search_tool_result_error"}},{"type":"web_search_tool_result","tool_use_id":5,"content":[]},{"type":"web_search_tool_result","tool_use_id":"s5","content":"text"},{"type":{"web_search_tool_result":null},"tool_use_id":"s6","content":[]},{"type":"web_search_tool_result","tool_use_id":"s7","content":[["web_search_result"]]},{"type":"web_search_tool_result","tool_use_id":"s8","content":[{"type":{"web_search_result":null}}]},{"type":"web_search_tool_result","tool_use_id":"s9","content":{"type":{"web_search_tool_result_error":null}}},["web_search_tool_result","s10",[]],{"type":"web_search_tool_result","tool_use_id":"s11","content":[{"type":"web_search_tool_result_error"}]},{"type":"web_search_tool_result","tool_use_id":"s12","content":{"type":"web_search_result"}},{"type":"server_tool_use","tool_use_id":"s13","content":[]},{"type":"web_search_tool_result","content":[]},{"type":"web_search_result","url":"https://c.example"},{"type":"text","text":"unchanged"}]}]"#;
    let expected = r#"[{"role":"assistant","content":[{"type":"text","text":"Web search results for 'rust async':\n\nTitle: A\nURL: https://a.example\nSnippet: first\n\nURL: https://b.example"}]},{"role":"user","content":[{"type":"text","text":"Web search results:\n\n\n\nTitle: T\nSnippet: S"}]},{"role":"assistant","content":[{"type":"text","text":"Web search results:\n\nSearch failed: too_many_requests"},{"type":"text","text":"Web search results:\n\nSearch failed: unavailable"},{"type":"web_search_tool_result","tool_use_id":5,"content":[]},{"type":"web_search_tool_result","tool_use_id":"s5","content":"text"},{"type":{"web_search_tool_result":null},"tool_use_id":"s6","content":[]},{"type":"web_search_tool_result","tool_use_id":"s7","content":[["web_search_result"]]},{"type":"web_search_tool_result","tool_use_id":"s8","content":[{"type":{"web_search_result":null}}]},{"type":"web_search_tool_result","tool_use_id":"s9","content":{"type":{"web_search_tool_result_error":null}}},["web_search_tool_result","s10",[]],{"type":"web_search_tool_result","tool_use_id":"s11","content":[{"type":"web_search_tool_result_error"}]},{"type":"web_search_tool_result","tool_use_id":"s12","content":{"type":"web_search_result"}},{"type":"server_tool_use","tool_use_id":"s13","content":[]},{"type":"web_search_tool_result","content":[]},{"type":"web_search_result","url":"https://c.example"},{"type":"text","text":"unchanged"}]}]"#;
    assert_eq!(flatten(source), messages(expected));
}

#[test]
fn case_2_encrypted_search_preserved() {
    let source = r#"[{"role":"assistant","content":[{"type":"web_search_tool_result","tool_use_id":"e1","content":[{"type":"web_search_result","url":"https://a.example","encrypted_content":"cipher"}]},{"type":"web_search_tool_result","tool_use_id":"e2","content":[{"type":"web_search_result","url":"https://b.example"},{"type":"web_search_result","encrypted_content":"more"}]},{"type":"web_search_tool_result","tool_use_id":"e8","content":[{"type":"web_search_result","title":5}]},{"type":"web_search_tool_result","tool_use_id":"e3","content":[{"type":"web_search_result","url":"https://c.example","encrypted_content":""}]}]},{"role":"user","content":[{"type":"web_search_tool_result","tool_use_id":"e4","content":[{"type":"web_search_result","encrypted_content":"x"}]},{"type":"server_tool_use","id":"e4","input":{"query":"kept"}}]},null,7,"text",{"role":"user","content":"plain string"},{"content":{"type":"web_search_tool_result","tool_use_id":"e5","content":[]}},{"content":[]},{"role":"assistant"},{"content":null},{"content":[{"type":"web_search_tool_result","tool_use_id":"e6","content":[{"type":"web_search_result","title":"only title"}]}]},{"role":"assistant","name":"helper","content":[{"type":"web_search_tool_result","tool_use_id":"e7","content":[{"type":"web_search_result","url":"https://d.example"}]}]}]"#;
    let expected = r#"[{"role":"assistant","content":[{"type":"web_search_tool_result","tool_use_id":"e1","content":[{"type":"web_search_result","url":"https://a.example","encrypted_content":"cipher"}]},{"type":"web_search_tool_result","tool_use_id":"e2","content":[{"type":"web_search_result","url":"https://b.example"},{"type":"web_search_result","encrypted_content":"more"}]},{"type":"web_search_tool_result","tool_use_id":"e8","content":[{"type":"web_search_result","title":5}]},{"type":"text","text":"Web search results:\n\nURL: https://c.example"}]},{"role":"user","content":[{"type":"web_search_tool_result","tool_use_id":"e4","content":[{"type":"web_search_result","encrypted_content":"x"}]},{"type":"server_tool_use","id":"e4","input":{"query":"kept"}}]},null,7,"text",{"role":"user","content":"plain string"},{"content":{"type":"web_search_tool_result","tool_use_id":"e5","content":[]}},{"content":[]},{"role":"assistant"},{"content":null},{"content":[{"type":"text","text":"Web search results:\n\nTitle: only title"}]},{"role":"assistant","name":"helper","content":[{"type":"text","text":"Web search results:\n\nURL: https://d.example"}]}]"#;
    assert_eq!(flatten(source), messages(expected));
}

#[test]
fn case_3_server_tool_correlation() {
    let source = r#"[{"role":"assistant","content":[{"type":"web_search_tool_result","tool_use_id":"dup","content":[{"type":"web_search_result","url":"u"}]},{"type":"server_tool_use","id":"dup","name":"web_search","input":{"query":"first"}},{"type":"server_tool_use","id":"dup","name":"other_name","input":{"query":"last"}},{"type":"server_tool_use","id":"unmatched","input":{"query":"q"}},{"type":"server_tool_use","id":"kept","name":"other"},{"type":"server_tool_use","id":7,"input":{"query":"bad-id"}},{"type":"server_tool_use","input":{"query":"no-id"}},{"type":"server_tool_use","id":"badinput","input":{"query":7}},{"type":"server_tool_use","id":"nullinput","input":null},{"type":{"server_tool_use":null},"id":"dup","input":{"query":"map-type"}},{"type":"server_tool_use","id":"dup","input":[]},["server_tool_use","dup",{"query":"array"}],{"type":"web_search_tool_result","id":"dup","input":{}}]},{"role":"assistant","content":[{"type":"server_tool_use","id":"later","input":{"query":"later query"}},{"type":"web_search_tool_result","tool_use_id":"later","content":[{"type":"web_search_result","url":"u"}]},{"type":"web_search_tool_result","tool_use_id":"nomatch","content":[{"type":"web_search_result","url":"v"}]}]}]"#;
    let expected = r#"[{"role":"assistant","content":[{"type":"text","text":"Web search results for 'last':\n\nURL: u"},{"type":"server_tool_use","id":"unmatched","input":{"query":"q"}},{"type":"server_tool_use","id":"kept","name":"other"},{"type":"server_tool_use","id":7,"input":{"query":"bad-id"}},{"type":"server_tool_use","input":{"query":"no-id"}},{"type":"server_tool_use","id":"badinput","input":{"query":7}},{"type":"server_tool_use","id":"nullinput","input":null},{"type":{"server_tool_use":null},"id":"dup","input":{"query":"map-type"}},{"type":"server_tool_use","id":"dup","input":[]},["server_tool_use","dup",{"query":"array"}],{"type":"web_search_tool_result","id":"dup","input":{}}]},{"role":"assistant","content":[{"type":"text","text":"Web search results for 'later query':\n\nURL: u"},{"type":"text","text":"Web search results:\n\nURL: v"}]}]"#;
    assert_eq!(flatten(source), messages(expected));
}

#[test]
fn case_4_missing_search_title_url() {
    let source = r#"[{"content":[{"type":"web_search_tool_result","tool_use_id":"q1","content":[{"type":"web_search_result","title":"Only title"},{"type":"web_search_result","url":"https://u.example"},{"type":"web_search_result","snippet":"Only snippet"},{"type":"web_search_result","title":"T","url":"https://u2.example","snippet":"S"}]},{"type":"web_search_tool_result","tool_use_id":"q2","content":[]},{"type":"web_search_tool_result","tool_use_id":"q3","content":{"type":"web_search_tool_result_error"}},{"type":"web_search_tool_result","tool_use_id":"q4","content":[{"type":"web_search_result"}]},{"type":"web_search_tool_result","tool_use_id":"q5","content":[{"type":"web_search_result"},{"type":"web_search_result"}]},{"type":"server_tool_use","id":"q1","input":{"query":" padded query "}},{"type":"server_tool_use","id":"q2","input":{"query":""}},{"type":"server_tool_use","id":"q4","input":{}}]},{"content":[{"type":"web_search_tool_result","tool_use_id":"q6","content":{"type":"web_search_tool_result_error","error_code":"invalid_tool_input"}}]}]"#;
    let expected = r#"[{"content":[{"type":"text","text":"Web search results for ' padded query ':\n\nTitle: Only title\n\nURL: https://u.example\n\nSnippet: Only snippet\n\nTitle: T\nURL: https://u2.example\nSnippet: S"},{"type":"text","text":"Web search results:\n\nNo results were returned."},{"type":"text","text":"Web search results:\n\nSearch failed: unavailable"},{"type":"text","text":"Web search results:"},{"type":"text","text":"Web search results:\n\n\n\n"}]},{"content":[{"type":"text","text":"Web search results:\n\nSearch failed: invalid_tool_input"}]}]"#;
    assert_eq!(flatten(source), messages(expected));
}
